#!/usr/bin/env python3
"""Build this decompilation and check the result against your own copy of the game, byte for byte.

    python build.py              disassemble your copy (first run), build, compare
    python build.py check NAME   check one function's C (src/NAME.c) against the original
    python build.py status       how many functions are C so far

The ROM is built from pieces, each at its original address (build/game.ld, generated on every build): luvdis's
assembly of your copy, split at the functions, and the decompiled functions compiled with agbcc. A function with C
replaces its assembly. Generated by decomp.wtf (https://decomp.wtf), which provides the pinned tools.
"""

from __future__ import annotations

import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
B = json.loads((ROOT / "build.json").read_text(encoding="utf-8"))
AS_FLAGS = ["-mcpu=arm7tdmi", "-I", "asm"]
_START = re.compile(r"^\s*(?:thumb|arm|non_word_aligned_thumb)_func_start\s+(\S+)")
_LABEL = re.compile(r"\b(_[0-9A-F]{8})\b")

try:
    from decompnet import toolchains
    from decompnet.compiler import run_in
    from decompnet.project import compiler_config
except ImportError:
    sys.exit("This build uses decomp.wtf's pinned tools: install decomp.wtf first (https://decomp.wtf).")


def fail(msg: str) -> None:
    sys.exit(f"error: {msg}")


def run(argv: list[str]) -> None:
    res = subprocess.run(argv, cwd=ROOT, capture_output=True, text=True, encoding="utf-8", errors="replace")
    if res.returncode != 0:
        fail(f"{' '.join(Path(a).name if i == 0 else a for i, a in enumerate(argv[:3]))} ...\n{(res.stdout + res.stderr)[-3000:]}")


def arm(tool: str) -> str:
    return str(toolchains.ensure("arm-gnu", log=lambda *_: None) / "bin" / f"arm-none-eabi-{tool}")


def setup() -> None:
    base = ROOT / B["image"]
    if not base.exists():
        fail(f"put your own copy of the game here as {B['image']} (see README.md)")
    if hashlib.sha1(base.read_bytes()).hexdigest() != B["sha1"]:
        fail(f"{B['image']} isn't the version this project decompiles (its SHA-1 differs)")
    if not (ROOT / "asm" / "pieces.json").exists():
        disassemble()


def disassemble() -> None:
    """luvdis's assembly of your copy, with the names in functions.cfg, split into one file per function."""
    from decompnet.rom.gba import _luvdis

    print("disassembling your copy (luvdis)")
    work = ROOT / "build" / "luvdis"
    work.mkdir(parents=True, exist_ok=True)
    text, _ = _luvdis(ROOT / B["image"], work, ROOT / "functions.cfg")
    end = text.index("@ End embedded Luvdis macros")
    end = text.index("\n", end) + 1
    asm = ROOT / "asm"
    asm.mkdir(exist_ok=True)
    (asm / "macros.inc").write_text(text[:end].replace(".syntax unified\n", "").replace(".text\n", ""),
                                    encoding="utf-8")
    addr = {f["name"]: f["addr"] for f in B["functions"]}
    pieces, cur, lines = [], B["base"], []

    def flush() -> None:
        if any(ln.strip() for ln in lines):
            first = next((m.group(1) for ln in lines if (m := _START.match(ln))), None)
            name = first if first and addr.get(first) == cur else "rom_header" if cur == B["base"] else f"_{cur:08X}"
            path = asm / f"{name}.s"
            path.write_text('.syntax unified\n.include "macros.inc"\n.text\n' + "\n".join(lines) + "\n",
                            encoding="utf-8")
            pieces.append({"addr": cur, "src": path.relative_to(ROOT).as_posix(), "name": name})

    for line in text[end:].splitlines():
        m = _START.match(line)
        if m and m.group(1) in addr and addr[m.group(1)] % 4 == 0 and addr[m.group(1)] != cur:
            flush()
            cur, lines = addr[m.group(1)], []
        lines.append(line)
    flush()
    (asm / "pieces.json").write_text(json.dumps(pieces, indent=1), encoding="utf-8")


def c_source(fn: dict) -> str | None:
    path = fn.get("c") or f"src/{fn['name']}.c"
    return path if (ROOT / path).exists() and fn["addr"] % 4 == 0 else None


def trim(path: Path) -> None:
    """Shrink a compiled object's .text to where its function ends. The assembler pads Thumb code to a whole word
    with `nop`; in the game the next function's alignment supplied those bytes (and they may differ)."""
    import struct
    from io import BytesIO

    from elftools.elf.elffile import ELFFile

    from decompnet.elfobj import _function_symbols

    data = bytearray(path.read_bytes())
    elf = ELFFile(BytesIO(bytes(data)))
    ends: dict[int, int] = {}
    for shndx, off, size in _function_symbols(elf).values():
        ends[shndx] = max(ends.get(shndx, 0), (off & ~1) + size)
    shoff, shentsize = struct.unpack_from("<I", data, 0x20)[0], struct.unpack_from("<H", data, 0x2E)[0]
    for shndx, end in ends.items():
        sec = elf.get_section(shndx)
        relocated = any(r["r_offset"] >= end for rs in elf.iter_sections()
                        if rs.header["sh_type"] in ("SHT_REL", "SHT_RELA") and rs["sh_info"] == shndx
                        for r in rs.iter_relocations())
        tail = sec.data()[end:]
        if end < sec["sh_size"] and (not tail.strip(b"\0") or tail == b"\xc0\x46" * (len(tail) // 2)) and not relocated:
            struct.pack_into("<I", data, shoff + shndx * shentsize + 20, end)
    path.write_bytes(bytes(data))


def build_objects() -> tuple[list[dict], dict[str, str]]:
    """Assemble every piece and compile every C function: (pieces, function name -> its C object)."""
    pieces = json.loads((ROOT / "asm" / "pieces.json").read_text(encoding="utf-8"))
    for p in pieces:
        p["obj"] = f"build/{Path(p['src']).with_suffix('.o').as_posix()}"
        target = ROOT / p["obj"]
        target.parent.mkdir(parents=True, exist_ok=True)
        if not target.exists() or target.stat().st_mtime < (ROOT / p["src"]).stat().st_mtime:
            run([arm("as"), *AS_FLAGS, "-o", p["obj"], p["src"]])
    cfg = compiler_config(ROOT, {"compiler": B["compiler"]})
    c_objs = {}
    for fn in B["functions"]:
        src = c_source(fn)
        if not src:
            continue
        obj = f"build/{Path(src).with_suffix('.o').as_posix()}"
        (ROOT / obj).parent.mkdir(parents=True, exist_ok=True)
        argv = [a.replace("{src}", src).replace("{obj}", obj).replace("{include}", "include") for a in cfg.cmd]
        res = run_in(cfg, ROOT, argv, inputs=[src, "include"], outputs=[obj])
        if res.returncode != 0 or not (ROOT / obj).exists():
            fail(f"compiling {src} failed:\n{(res.stdout + res.stderr)[-3000:]}")
        trim(ROOT / obj)
        c_objs[fn["name"]] = obj
    return pieces, c_objs


def _text_size(obj: str) -> int:
    from elftools.elf.elffile import ELFFile

    with open(ROOT / obj, "rb") as f:
        return sum(s["sh_size"] for s in ELFFile(f).iter_sections() if s.name == ".text")


def _globals(obj: str) -> set[str]:
    from elftools.elf.elffile import ELFFile

    with open(ROOT / obj, "rb") as f:
        symtab = ELFFile(f).get_section_by_name(".symtab")
        return {s.name for s in symtab.iter_symbols() if s["st_info"]["bind"] == "STB_GLOBAL"
                and s["st_shndx"] != "SHN_UNDEF"} if symtab else set()


def layout(pieces: list[dict], c_objs: dict[str, str]) -> list[tuple[int, str, str]]:
    """(address, object, sections) of everything in the ROM, with your copy's bytes wherever nothing else is."""
    by_addr = {fn["addr"]: fn for fn in B["functions"]}
    items = []
    for p in pieces:
        fn = by_addr.get(p["addr"])
        if fn is not None and fn["name"] in c_objs and p["name"] == fn["name"]:
            continue  # the function's C replaces its assembly
        items.append((p["addr"], p["obj"], ".text .data .rodata"))
    for name, obj in c_objs.items():
        items.append((next(f["addr"] for f in B["functions"] if f["name"] == name), obj, ".text"))
    image = (ROOT / B["image"]).read_bytes()
    pos, end, gaps = B["base"], B["base"] + len(image), []
    for addr, obj, _ in [*sorted(items), (end, None, "")]:
        if addr > pos:
            raw = image[pos - B["base"]:addr - B["base"]]
            src = ROOT / "build" / "gaps" / f"{pos:08X}.s"
            src.parent.mkdir(parents=True, exist_ok=True)
            src.write_text(".data\n" + "".join(f".byte {', '.join(str(b) for b in raw[i:i + 16])}\n"
                                               for i in range(0, len(raw), 16)), encoding="utf-8")
            gobj = f"build/gaps/{pos:08X}.o"
            run([arm("as"), *AS_FLAGS, "-o", gobj, src.relative_to(ROOT).as_posix()])
            gaps.append((pos, gobj, ".data"))
        if obj is not None:
            pos = max(pos, addr + _text_size(obj))
    return sorted(items + gaps)


def linker_script(items: list[tuple[int, str, str]], c_objs: dict[str, str]) -> str:
    lines = ["/* Generated by build.py: every piece of the ROM at its original address. */", "SECTIONS", "{",
             f"    .rom 0x{B['base']:08X} : AT(0x{B['base']:08X})", "    {"]
    lines += [f"        . = 0x{addr - B['base']:X}; {obj}({sections})" for addr, obj, sections in items]
    lines.append("    }")
    n = 0
    for fn in B["functions"]:
        for section, base in (fn.get("own") or {}).items():
            if fn["name"] in c_objs:
                lines.append(f"    .own_{n} 0x{base:08X} (NOLOAD) : {{ {c_objs[fn['name']]}({section}) }}")
                n += 1
    # own data of C functions nobody placed yet (`build.py check` places it): kept out of the image
    lines.append("    .unplaced 0xF0000000 (NOLOAD) : { build/src/*(.rodata .rodata.* .data .data.* .bss .bss.* COMMON) }")
    lines += ["    /DISCARD/ : { *(.comment) *(.note*) }", "}", ""]
    linked = {obj for _, obj, _ in items}
    defined = set().union(*(_globals(obj) for obj in linked))
    wanted = {fn["name"]: fn["addr"] for fn in B["functions"]} | B["symbols"]
    # luvdis's labels (_08001234) jumped to from another piece: their names are their addresses
    for p in json.loads((ROOT / "asm" / "pieces.json").read_text(encoding="utf-8")):
        text = (ROOT / p["src"]).read_text(encoding="utf-8")
        own = set(re.findall(r"^(_[0-9A-F]{8}):", text, re.MULTILINE))
        wanted.update({lab: int(lab[1:], 16) for lab in set(_LABEL.findall(text)) - own})
        wanted.update({name: int(name[4:], 16) for name in re.findall(r"\b(sub_[0-9A-F]{8})\b", text)})
    lines += [f"{name} = 0x{addr:08X};" for name, addr in sorted(wanted.items(), key=lambda kv: kv[1]) if name not in defined]
    return "\n".join(lines) + "\n"


def build() -> bool:
    setup()
    pieces, c_objs = build_objects()
    items = layout(pieces, c_objs)
    (ROOT / "build" / "game.ld").write_text(linker_script(items, c_objs), encoding="utf-8")
    objs = sorted({obj for _, obj, _ in items} | set(c_objs.values()))
    run([arm("ld"), "-e", f"0x{B['base']:X}", "-T", "build/game.ld", "-o", "build/game.elf", *objs])
    run([arm("objcopy"), "-O", "binary", "build/game.elf", B["output"]])
    out, base = (ROOT / B["output"]).read_bytes(), (ROOT / B["image"]).read_bytes()
    if out == base:
        print(f"identical: {B['output']} matches {B['image']} byte for byte "
              f"({len(c_objs)} of {len(B['functions'])} functions in C)")
        return True
    at = next((i for i in range(min(len(out), len(base))) if out[i] != base[i]), min(len(out), len(base)))
    where = next((fn["name"] for fn in sorted(B["functions"], key=lambda f: f["addr"], reverse=True)
                  if fn["addr"] - B["base"] <= at), "the header")
    print(f"differs: first difference at 0x{B['base'] + at:08X} (in or after {where}); sizes {len(out)} vs {len(base)}")
    return False


def check(name: str) -> bool:
    """Compile one function and compare it with the original at its address; record where its own data goes."""
    from decompnet.compiler import compile_source
    from decompnet.rom import match_arm
    from decompnet.rom.symbols import Symbol, SymbolTable

    setup()
    fn = next((f for f in B["functions"] if f["name"] == name), None)
    if fn is None:
        fail(f"no function {name}")
    src = c_source(fn)
    if not src:
        fail(f"write it first as src/{name}.c")
    image = (ROOT / B["image"]).read_bytes()
    base = B["base"]
    table = SymbolTable([Symbol(s, a, 0, "data") for s, a in B["symbols"].items()]
                        + [Symbol(f["name"], f["addr"], f["size"], "func") for f in B["functions"]])
    target = match_arm.ArmTarget(name, fn["addr"], image[fn["addr"] - base:fn["addr"] - base + fn["size"]], fn["thumb"])

    def read(addr: int, n: int) -> bytes | None:
        return image[addr - base:addr - base + n] if base <= addr and addr + n <= base + len(image) else None

    cfg = compiler_config(ROOT, {"compiler": B["compiler"]})
    text = (ROOT / src).read_text(encoding="utf-8")
    m = re.match(r'\s*#include "([^"]+)"\s*\n', text)
    header = (ROOT / "include" / m.group(1)).read_text(encoding="utf-8") if m else ""
    res = compile_source(cfg, header, text[m.end():] if m else text, trusted=True)
    if not res.ok:
        print(res.log)
        return False
    linked = match_arm.link(res.obj, name, target, table, read)
    if not linked.exact:
        print(f"{name}: not identical yet")
        for p in linked.problems:
            print(f"  - {p}")
        return False
    fn["c"] = src
    fn["own"] = {sec: min(a - o for o, a in offs.items()) for sec, offs in linked.placements.items()}
    (ROOT / "build.json").write_text(json.dumps(B, indent=1), encoding="utf-8")
    print(f"{name}: identical to the original; recorded in build.json")
    return True


def status() -> None:
    c = [fn["name"] for fn in B["functions"] if c_source(fn)]
    print(f"{len(c)} of {len(B['functions'])} functions are C ({100 * len(c) / max(1, len(B['functions'])):.1f}%)")


if __name__ == "__main__":
    args = sys.argv[1:]
    if args[:1] == ["check"] and len(args) == 2:
        sys.exit(0 if check(args[1]) else 1)
    if args[:1] == ["status"]:
        status()
        sys.exit(0)
    sys.exit(0 if build() else 1)
